(function(){'use strict';
const poses=[{"id":1,"label":"笑顔","file":"assets/coach-eight/coach-01-smile.png"},{"id":2,"label":"ふつう","file":"assets/coach-eight/coach-02-neutral.png"},{"id":3,"label":"発見","file":"assets/coach-eight/coach-03-discovery.png"},{"id":4,"label":"応援","file":"assets/coach-eight/coach-04-cheer.png"},{"id":5,"label":"真剣","file":"assets/coach-eight/coach-05-serious.png"},{"id":6,"label":"考える","file":"assets/coach-eight/coach-06-thinking.png"},{"id":7,"label":"しょんぼり","file":"assets/coach-eight/coach-07-downcast.png"},{"id":8,"label":"ひと息","file":"assets/coach-eight/coach-08-rest.png"}],portrait=document.querySelector('.home-coach');let selected=2,lastFocus=null;
const picker=document.createElement('dialog');picker.id='coach-picker';picker.setAttribute('aria-labelledby','coach-picker-title');picker.innerHTML='<div class="coach-picker-heading"><h2 id="coach-picker-title">COACHの表情</h2><button type="button" id="coach-picker-close">閉じる</button></div><div class="coach-pose-grid"></div>';document.body.append(picker);
function choose(id){const pose=poses.find(p=>p.id===id);if(!pose)return;selected=id;portrait.src=pose.file;portrait.dataset.pose=String(id);document.documentElement.style.setProperty('--coach-image','url("'+pose.file+'")');picker.querySelectorAll('[data-coach-pose]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.coachPose)===id)));}
function openChooser(){lastFocus=document.activeElement;picker.showModal();picker.querySelector('[data-coach-pose="'+selected+'"]').focus({preventScroll:true})}
function closeChooser(){picker.close();lastFocus?.focus({preventScroll:true})}
for(const pose of poses){const b=document.createElement('button');b.type='button';b.dataset.coachPose=String(pose.id);b.setAttribute('aria-label',pose.id+' '+pose.label);b.innerHTML='<img src="'+pose.file+'" alt=""><span>'+pose.label+'</span>';b.addEventListener('click',()=>{choose(pose.id);closeChooser()});picker.querySelector('.coach-pose-grid').append(b)}
picker.querySelector('#coach-picker-close').addEventListener('click',closeChooser);picker.addEventListener('cancel',()=>queueMicrotask(()=>lastFocus?.focus({preventScroll:true})));
const homeButton=document.createElement('button');homeButton.type='button';homeButton.textContent='表情を選ぶ';homeButton.className='home-expression-button';homeButton.addEventListener('click',openChooser);portrait.after(homeButton);
const old=document.querySelector('.coach-title-avatar'),avatar=document.createElement('button');avatar.type='button';avatar.className='coach-title-avatar';avatar.setAttribute('aria-label','COACHの表情を選ぶ');avatar.title='表情を選ぶ';avatar.addEventListener('click',openChooser);old.replaceWith(avatar);avatar.closest('h1').setAttribute('aria-label','COACH');
window.WHYCoach={openChooser};choose(2);
})();